response.text:
{
  "title": "HCV Adherence in Zimbabwe",
  "perWatchSecond": 3,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "When everyone takes their medicine",
      "goal": "See how full treatment adherence eliminates the quit-treatment group and stops the epidemic from being sustained.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "0.25",
        "highEnd": "1"
      },
      "watch": "Those who quit treatment (cq)",
      "whatIf": {
        "prompt": "What if every patient sticks to treatment perfectly?",
        "parameter": "theta",
        "value": 1
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 60,
        "relation": "lower",
        "by": 0.014
      },
      "effect": "With full adherence, the peak of those who quit treatment falls from 0.014 to zero, because no one leaves treatment.",
      "prediction": {
        "prompt": "In the base world some patients quit treatment. In the What-if world no one quits. Which world has a higher peak of quitters?",
        "claimed": "Base world higher",
        "other": "What-if world higher"
      },
      "passage": {
        "title": "Headline result",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Full adherence removes the quit-treatment group entirely. Now let us see which infected group spreads the virus most."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "Quitters are the biggest spreaders",
      "goal": "See how doubling transmission from those who quit treatment raises the total number who eventually recover.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission from quitters",
        "lowEnd": "0.025",
        "highEnd": "0.1"
      },
      "watch": "Recovered (r)",
      "whatIf": {
        "prompt": "What if quitters spread the virus twice as fast?",
        "parameter": "beta3",
        "value": 0.1
      },
      "difference": {
        "compartment": "r",
        "summary": "peak",
        "at": null,
        "time": 80,
        "relation": "higher",
        "by": 0.019
      },
      "effect": "Doubling transmission from quitters raises the peak of recovered from 0.023 to 0.042, as more people get infected and eventually recover.",
      "prediction": {
        "prompt": "If quitters spread the virus twice as fast, more people get infected. Does the peak of recovered go up or down?",
        "claimed": "What-if world higher",
        "other": "Base world higher"
      },
      "passage": {
        "title": "Strongest influence",
        "quote": "$β_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Quitters drive transmission more than any other group. Now let us see what happens when the acute stage lasts longer."
    },
    {
      "kind": "result",
      "finding": 3,
      "title": "A longer acute stage means more spread",
      "goal": "See how slowing the exit from the acute stage increases the peak of acute infection, one half of the synergy the paper reports.",
      "control": {
        "parameter": "r2",
        "label": "Rate of leaving acute stage",
        "lowEnd": "0.08",
        "highEnd": "0.33"
      },
      "watch": "Acutely infected (i)",
      "whatIf": {
        "prompt": "What if the acute stage lasts twice as long?",
        "parameter": "r2",
        "value": 0.0815
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 60,
        "relation": "higher",
        "by": 0.06
      },
      "effect": "Halving the rate of leaving the acute stage raises the peak of acutely infected from 0.013 to 0.073, because each person stays infectious longer.",
      "prediction": {
        "prompt": "If people stay in the acute stage twice as long, does the peak of acute infection go up or down?",
        "claimed": "What-if world higher",
        "other": "Base world higher"
      },
      "passage": {
        "title": "Synergistic impact",
        "quote": "Our model unraveled the synergistic impact of simultaneously enhancing the recovery rate of acutely infected individuals and treatment adherence on reducing $ℛ_{0}$."
      },
      "carryForward": "The acute recovery rate matters for transmission. Now let us see what happens when the epidemic starts with far more infected people."
    },
    {
      "kind": "result",
      "finding": 5,
      "title": "A big start keeps the fire burning",
      "goal": "See how a much larger initial infection sustains the epidemic even when the reproduction number is below one.",
      "control": {
        "parameter": "beta1",
        "label": "Transmission from acute",
        "lowEnd": "0.11",
        "highEnd": "0.43"
      },
      "watch": "Acutely infected (i)",
      "whatIf": {
        "prompt": "What if ten times as many people start out acutely infected?",
        "parameter": "i0",
        "value": 0.1
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 80,
        "relation": "higher",
        "by": 0.08
      },
      "effect": "Starting with 0.1 acutely infected instead of 0.01 raises the peak of acute infection from 0.013 to about 0.1, because the larger initial pool sustains transmission.",
      "prediction": {
        "prompt": "If the epidemic starts with ten times more acute cases, does the peak of acute infection go up or down?",
        "claimed": "What-if world higher",
        "other": "Base world higher"
      },
      "passage": {
        "title": "Backward bifurcation",
        "quote": "even if $ℛ_{0} < 1$, the disease may persist due to the coexistence of multiple stable equilibria."
      },
      "carryForward": "Even below the epidemic threshold, a large start keeps the disease going. This is backward bifurcation in action."
    },
    {
      "kind": "method",
      "finding": null,
      "title": "More births, more cases",
      "goal": "See how doubling the recruitment of new susceptibles feeds the epidemic and raises the long-run recovered count.",
      "control": {
        "parameter": "b",
        "label": "Recruitment rate",
        "lowEnd": "0.005",
        "highEnd": "0.02"
      },
      "watch": "Recovered (r)",
      "whatIf": {
        "prompt": "What if twice as many new people enter the population each year?",
        "parameter": "b",
        "value": 0.02
      },
      "difference": {
        "compartment": "r",
        "summary": "at",
        "at": 200,
        "time": 200,
        "relation": "higher",
        "by": 0.11
      },
      "effect": "Doubling the recruitment rate raises the recovered count at year 200 from 0.004 to 0.117, because more susceptible people enter and eventually get infected.",
      "prediction": {
        "prompt": "If twice as many new people join the population each year, does the recovered count at year 200 go up or down?",
        "claimed": "What-if world higher",
        "other": "Base world higher"
      },
      "passage": null,
      "carryForward": "Recruitment feeds the susceptible pool. Together with adherence and transmission rates, it shapes the epidemic's long-run course."
    }
  ],
  "limits": [
    "At the values the paper lists in Table 1, R0 stays between 0.65 and 0.78 for every adherence from 0 to 1, so the 52% threshold does not appear here; the paper's figure may use values it does not list.",
    "Compartments are shares of the population and sum to one; a value of 0.02 means 2 percent of the population.",
    "The time unit is years; a run of 200 years shows the long-run approach to equilibrium.",
    "The What-if world changes exactly one parameter or one starting value; all other values stay at the paper's listed values.",
    "A compartment drawn through a lens is magnified so that small differences remain visible as at least three figures in the town scene."
  ]
}
